package org.apache.commons.lang.time;

import junit.framework.TestCase;
import java.util.Calendar;

public class AgentBRT_Lang_63_raw_diff_Test extends TestCase {

    public void testReproduceBug() {
        Calendar start = Calendar.getInstance();
        Calendar end = Calendar.getInstance();

        // Set start to January 31st
        start.set(2023, Calendar.JANUARY, 31);
        // Set end to March 1st
        end.set(2023, Calendar.MARCH, 1);

        // Attempt to reduce end by 1 month and 1 day
        int daysReduced = DurationFormatUtils.reduceAndCorrect(start, end, Calendar.DAY_OF_MONTH, 1);
        int monthsReduced = DurationFormatUtils.reduceAndCorrect(start, end, Calendar.MONTH, 1);

        // Check if the end date is correctly adjusted
        assertEquals("End day should be 31 after reduction", 31, end.get(Calendar.DAY_OF_MONTH));
        assertEquals("End month should be January after reduction", Calendar.JANUARY, end.get(Calendar.MONTH));
    }
}

